import assert from 'node:assert';
import _ from 'lodash';
import { DateTime, type Interval } from 'luxon';
import type { Valid } from 'luxon/src/_util';
import { checkIsQuarterHour } from '../dateutil';
import { DataInterval } from './data-interval';

interface DataIntervalPartitionMap {
  [key: string]: DataIntervalPartition<any>;
}

type ExtractValueType<Type> = Type extends DataIntervalPartition<infer ValueType> ? ValueType : unknown;

/**
 * A list of DataIntervals which 'partition' a time interval. This class guarantees:
 * - no overlapping data intervals
 * - no gaps between data intervals
 */
export class DataIntervalPartition<ValueType> {
  private constructor(private readonly partitions: DataInterval<ValueType>[]) {}

  static fromIntervalList<ValueType>(intervals: DataInterval<ValueType>[]) {
    assert.notEqual(intervals.length, 0, 'DataIntervalPartition must contain at least one DataInterval');

    const allButLastOne = _.take(intervals, intervals.length - 1);
    const allButFirstOne = _.takeRight(intervals, intervals.length - 1);

    const intervalPairs = _.zip(allButLastOne, allButFirstOne);
    intervalPairs.forEach((pair, index) => {
      const first = pair[0] as DataInterval<ValueType>;
      const second = pair[1] as DataInterval<ValueType>;
      if (first.getStart() >= second.getStart()) {
        throw new Error(`intervals are not sorted by start date (at position ${index})`);
      }

      if (first.getEnd() < second.getStart()) {
        throw new Error(`intervals have gaps (at position ${index})`);
      }

      if (first.getEnd() > second.getStart()) {
        throw new Error(`intervals are overlapping (at position ${index})`);
      }
    });

    return new DataIntervalPartition(intervals);
  }

  static fromNullableValidPeriods<
    ValueType extends {
      validfrom: string | null;
      validto: string | null;
    },
  >(objects: ValueType[], containmentInterval: Interval<Valid>) {
    assert(_.filter(objects, (o) => o.validfrom === null).length <= 1, 'At most one object with validfrom == null is allowed');
    assert(_.filter(objects, (o) => o.validto === null).length <= 1, 'At most one object with validto == null is allowed');

    assert(checkIsQuarterHour(containmentInterval.start), `containmentInterval start ${containmentInterval.start} must be a full quarter hour`);
    assert(checkIsQuarterHour(containmentInterval.end), `containmentInterval end ${containmentInterval.end} must be a full quarter hour`);

    const dataIntervals = _.chain(objects)
      .map((object) => DataInterval.fromNullableValidPeriod(object, containmentInterval))
      .compact()
      .sortBy((dataInterval) => +dataInterval.interval.start)
      .value();

    // The other conditions of the list of objects (e.g. no gaps, no overlaps) is checked in fromIntervalList.
    return DataIntervalPartition.fromIntervalList(dataIntervals).cut(containmentInterval);
  }

  static fromNullableIntervalListWithDefaultValue<ValueType, DefaultValueType = ValueType>(
    intervals: DataInterval<ValueType>[],
    defaultValue: DefaultValueType,
    containmentInterval: Interval<Valid>,
  ): DataIntervalPartition<ValueType | DefaultValueType> {
    if (intervals.length === 0) {
      return DataIntervalPartition.fromIntervalList([DataInterval.fromInterval(containmentInterval, defaultValue)]);
    }

    const sortedIntervals = _.chain(intervals)
      .sortBy((di) => +di.interval.start)
      .value();

    let intervalsWithoutGaps: DataInterval<ValueType | DefaultValueType>[] = fillGaps(sortedIntervals, defaultValue);

    const first = _.first(intervalsWithoutGaps) as DataInterval<ValueType>;
    if (+first.getStart() > +containmentInterval.start) {
      const defaultStart = DataInterval.from(containmentInterval.start, first.getStart(), defaultValue);
      intervalsWithoutGaps = [defaultStart, ...intervalsWithoutGaps];
    }
    const last = _.last(intervalsWithoutGaps) as DataInterval<ValueType>;
    if (+last.getEnd() < +containmentInterval.end) {
      const defaultEnd = DataInterval.from(last.getEnd(), containmentInterval.end, defaultValue);
      intervalsWithoutGaps = [...intervalsWithoutGaps, defaultEnd];
    }

    return DataIntervalPartition.fromIntervalList(intervalsWithoutGaps).cut(containmentInterval);
  }

  static fromNullableValidPeriodsWithDefaultValue<
    ValueType extends {
      validfrom: string | null;
      validto: string | null;
    },
    DefaultValueType = ValueType,
  >(objects: ValueType[], defaultValue: DefaultValueType, containmentInterval: Interval<Valid>): DataIntervalPartition<ValueType | DefaultValueType> {
    const dataIntervals = _.chain(objects)
      .map((object) => DataInterval.fromNullableValidPeriod(object, containmentInterval))
      .compact()
      .value();
    return DataIntervalPartition.fromNullableIntervalListWithDefaultValue(dataIntervals, defaultValue, containmentInterval);
  }

  static fromValidPeriods<
    ValueType extends {
      validfrom: string;
      validto: string;
    },
  >(objects: ValueType[]) {
    const dataIntervals = _.chain(objects)
      .map((object) => DataInterval.fromValidPeriod(object))
      .sortBy((dataInterval) => +dataInterval.interval.start)
      .value();

    // The other conditions of the list of objects (e.g. no gaps, no overlaps) is checked in fromIntervalList.
    return DataIntervalPartition.fromIntervalList(dataIntervals);
  }

  getPartitions() {
    // Return a copy of the list to prevent the caller from modifying the internal state.
    return this.partitions.map((partition) => partition);
  }

  getStart() {
    return this.partitions[0].getStart();
  }

  getEnd() {
    return this.partitions[this.partitions.length - 1].getEnd();
  }

  getValues() {
    return this.partitions.map((partition) => partition.value);
  }

  mergeIntervals(comparator: (a: ValueType, b: ValueType) => boolean = _.isEqual): DataIntervalPartition<ValueType> {
    // this entire method was produced by Github Copilot without any modifications from me :-O
    const merged: DataInterval<ValueType>[] = [];
    let currentInterval = this.partitions[0];
    for (let i = 1; i < this.partitions.length; i++) {
      const nextInterval = this.partitions[i];
      if (comparator(currentInterval.value, nextInterval.value)) {
        currentInterval = DataInterval.from(currentInterval.getStart(), nextInterval.getEnd(), currentInterval.value);
      } else {
        merged.push(currentInterval);
        currentInterval = nextInterval;
      }
    }
    merged.push(currentInterval);

    // We could also just invoke the private constructor since we know that `merged` is a valid
    // DataIntervalPartition. But I appreciate the extra checks in the public factory method.
    return DataIntervalPartition.fromIntervalList(merged);
  }

  cut(cutInterval: Interval<Valid>): DataIntervalPartition<ValueType> {
    assert(cutInterval.start >= this.getStart(), 'cut interval starts before data interval partition does');
    assert(cutInterval.end <= this.getEnd(), 'cut interval ends after data interval partition does');

    const newIntervals: DataInterval<ValueType>[] = [];
    this.partitions.forEach((dataInterval) => {
      if (dataInterval.getEnd() <= cutInterval.start || dataInterval.getStart() >= cutInterval.end) {
        // ignore these
      } else if (cutInterval.engulfs(dataInterval.interval)) {
        newIntervals.push(dataInterval);
      } else {
        newIntervals.push(
          DataInterval.from(DateTime.max(cutInterval.start, dataInterval.getStart()), DateTime.min(cutInterval.end, dataInterval.getEnd()), dataInterval.value),
        );
      }
    });
    return DataIntervalPartition.fromIntervalList(newIntervals);
  }

  extend(extendInterval: Interval<Valid>): DataIntervalPartition<ValueType> {
    assert(+extendInterval.start <= +this.getStart(), 'extend interval starts after data interval partition does');
    assert(+extendInterval.end >= +this.getEnd(), 'extend interval ends before data interval partition does');

    return DataIntervalPartition.fromIntervalList(
      this.partitions.map((partition, index) => {
        let updatedPartition = partition;
        if (index === 0 && +extendInterval.start < +updatedPartition.getStart()) {
          updatedPartition = DataInterval.from(extendInterval.start, updatedPartition.getEnd(), updatedPartition.value);
        }
        if (index === this.partitions.length - 1 && +extendInterval.end > +updatedPartition.getEnd()) {
          updatedPartition = DataInterval.from(updatedPartition.getStart(), extendInterval.end, updatedPartition.value);
        }
        return updatedPartition;
      }),
    );
  }

  /**
   * Similar to cut, but will fail if the selectInterval does not fully include a slice of the partitions,
   * i.e. if the selectInterval.start does not match any interval start or if the selectInterval.end does
   * not match any interval end.
   */
  select(selectInterval: Interval<Valid>): DataIntervalPartition<ValueType> {
    const startIndex = _.findIndex(this.partitions, (di) => +di.getStart() === +selectInterval.start);
    assert(startIndex !== -1, `Select interval start ${selectInterval.start} does not match any interval start`);

    // findLastIndex is a small optimization to start searching partitions from the end, assuming that the selectInterval will contain most or all of the partitions mostly.
    const endIndex = _.findLastIndex(this.partitions, (di) => +di.getEnd() === +selectInterval.end);
    assert(endIndex !== -1, `Select interval end ${selectInterval.end} does not match any interval end`);

    // Since a slice of the current partitions always fulfills the conditions of a DataIntervalPartition, we can just invoke the private constructor.
    return new DataIntervalPartition(this.partitions.slice(startIndex, endIndex + 1));
  }

  mapValues<NewValueType>(newValueMapper: (value: ValueType) => NewValueType) {
    const newPartitions = this.partitions.map((partition) => {
      const newValue = newValueMapper(partition.value);
      return DataInterval.fromInterval(partition.interval, newValue);
    });
    return DataIntervalPartition.fromIntervalList(newPartitions);
  }

  static crossProduct<CrossProductInput extends DataIntervalPartitionMap>(
    partitions: CrossProductInput,
  ): DataIntervalPartition<{ [K in keyof CrossProductInput]: ExtractValueType<CrossProductInput[K]> }> {
    assert.notEqual(Object.keys(partitions).length, 0, 'DataIntervalPartition.crossProduct must be invoked with at least one DataIntervalPartition');

    const startDates = _.chain(partitions)
      .values()
      .map((partition) => partition.getStart())
      .uniqBy((start) => +start)
      .value();
    assert.equal(startDates.length, 1, `There is no common start date for the partitions: ${startDates.join(', ')}`);

    const endDates = _.chain(partitions)
      .values()
      .map((partition) => partition.getEnd())
      .uniqBy((end) => +end)
      .value();
    assert.equal(endDates.length, 1, `There is no common end date for the partitions: ${endDates.join(', ')}`);

    const start = startDates[0];
    const end = endDates[0];

    const remainingIntervalsByKey = _.mapValues(partitions, (partition) => partition.getPartitions());

    let currentStart = start;
    const crossed: DataInterval<{ [K in keyof CrossProductInput]: ExtractValueType<CrossProductInput[K]> }>[] = [];

    while (!currentStart.equals(end)) {
      const minEndDateOfRemainingIntervalHeads = _.chain(remainingIntervalsByKey)
        .values()
        .map((intervals) => intervals[0].getEnd())
        .min()
        .value();

      const values = _.mapValues(remainingIntervalsByKey, (intervals) => intervals[0].value);
      crossed.push(DataInterval.from(currentStart, minEndDateOfRemainingIntervalHeads, values));

      // remove all intervals at the head that end at the minEndDateOfRemainingIntervalHeads
      _.forEach(remainingIntervalsByKey, (intervals, key) => {
        if (intervals[0].getEnd().equals(minEndDateOfRemainingIntervalHeads)) {
          _.pullAt(intervals, [0]); // this mutates intervals
